#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>

/* A small arbitrary-precision nonnegative integer, in base 1,000,000,000. */
typedef struct {
    uint32_t *d;
    size_t len;
    size_t cap;
} Big;

static void ensure(Big *x, size_t need) {
    if (need > x->cap) {
        size_t cap = x->cap ? x->cap : 1;
        while (cap < need) cap *= 2;
        x->d = realloc(x->d, cap * sizeof(*x->d));
        if (!x->d) { fputs("out of memory\n", stderr); exit(1); }
        x->cap = cap;
    }
}

static void add_into(Big *out, const Big *a, const Big *b) {
    const uint64_t base = UINT64_C(1000000000);
    size_t n = a->len > b->len ? a->len : b->len;
    ensure(out, n + 1);
    uint64_t carry = 0;
    for (size_t i = 0; i < n; ++i) {
        uint64_t v = carry;
        if (i < a->len) v += a->d[i];
        if (i < b->len) v += b->d[i];
        out->d[i] = (uint32_t)(v % base);
        carry = v / base;
    }
    if (carry) out->d[n++] = (uint32_t)carry;
    out->len = n;
}

static void print_big(const Big *x) {
    printf("%" PRIu32, x->d[x->len - 1]);
    for (size_t i = x->len - 1; i-- > 0;)
        printf("%09" PRIu32, x->d[i]);
    putchar('\n');
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s N\n", argv[0]);
        return 2;
    }
    char *end;
    unsigned long long n = strtoull(argv[1], &end, 10);
    if (*argv[1] == '\0' || *end != '\0') {
        fputs("N must be a nonnegative integer\n", stderr);
        return 2;
    }

    Big a = {0}, b = {0}, c = {0};
    ensure(&a, 1); a.d[0] = 0; a.len = 1;
    ensure(&b, 1); b.d[0] = 1; b.len = 1;
    for (unsigned long long i = 0; i < n; ++i) {
        add_into(&c, &a, &b);
        Big t = a; a = b; b = c; c = t;
    }
    print_big(&a);
    free(a.d); free(b.d); free(c.d);
    return 0;
}
